// ===== autoCheck: больше не молчит, шлёт только если рекорд лучше топа =====
let autoCheckRunning = false;
async function autoCheck() {
  if (autoCheckRunning) return;
  autoCheckRunning = true;
  try {
    const now = Date.now();

    if (now - STATE.lastSent < COOLDOWN_MS) {
      const left = Math.round((COOLDOWN_MS - (now - STATE.lastSent)) / 60000);
      console.log("[AUTO] cooldown active, " + left + " min left. skip.");
      autoCheckRunning = false;
      return;
    }

    if (BEST_RECORD >= 999) {
      console.log("[AUTO] no local record yet (BEST_RECORD=999), skip.");
      autoCheckRunning = false;
      return;
    }

    console.log("\n[AUTO] checking top... (local best=" + BEST_RECORD.toFixed(3) + "c)");

    let top = [];
    try {
      top = await fetchTop();
    } catch (e) {
      console.log("[AUTO] fetchTop FAILED: " + e.message);
      autoCheckRunning = false;
      return;
    }

    if (!top || top.length === 0) {
      console.log("[AUTO] top empty or not received, sending anyway...");
      await sendRecord(BEST_RECORD);
      STATE.lastSent = now;
      STATE.bestSent = BEST_RECORD;
      saveState();
      autoCheckRunning = false;
      return;
    }

    // ищем свою лучшую запись в топе
    let ourBest = Infinity;
    let ourEntry = null;
    for (const s of top) {
      if (s && s.nick && s.nick.includes(NICK)) {
        const tt = parseFloat(s.time);
        if (!isNaN(tt) && tt < ourBest) { ourBest = tt; ourEntry = s; }
      }
    }

    if (ourEntry) {
      console.log("[AUTO] our top entry: " + ourBest.toFixed(3) + "c");
    } else {
      console.log("[AUTO] we are NOT in top");
    }

    // шлём только если локальный рекорд строго лучше того, что в топе
    if (ourBest <= BEST_RECORD) {
      console.log("[AUTO] top already has better/equal (" + ourBest + " <= " + BEST_RECORD.toFixed(3) + "), skip.");
      // обновим lastSent чтобы не спамить проверками
      STATE.lastSent = now;
      saveState();
      autoCheckRunning = false;
      return;
    }

    console.log("[AUTO] sending " + BEST_RECORD.toFixed(3) + "c (beats top " + (ourEntry?ourBest:"none") + ")");
    await sendRecord(BEST_RECORD);
    STATE.lastSent = now;
    STATE.bestSent = BEST_RECORD;
    saveState();
    console.log("[AUTO] sent ok, next check in 24h.");
  } catch (e) {
    console.log("[AUTO] err: " + e.message);
  }
  autoCheckRunning = false;
}

const EMBEDDED_DEMOS = ["","","","","","","","","","","","","","","","","","","",""];
let DEMOS = [];
for (const b64 of EMBEDDED_DEMOS) {
  try {
    const buf = Buffer.from(b64, "base64");
    const d = JSON.parse(zlib.gunzipSync(buf).toString("utf-8"));
    const path = d.frames.map(f => ({ x: f.x/1e5, y: f.y/1e5, z: f.z/1e5, t: f.t }));
    if (path.length < 5) continue;
    DEMOS.push({ path, time: path[path.length-1].t });
  } catch (e) {}
}
if (!DEMOS.length) { console.log("no demos"); process.exit(1); }
console.log("loaded " + DEMOS.length + " embedded demos");

const minT = Math.min(...DEMOS.map(d => d.time));
const maxT = Math.max(...DEMOS.map(d => d.time));
for (const d of DEMOS) {
  const norm = (d.time - minT) / Math.max(maxT - minT, 0.001);
  d.weight = 3.0 - 2.0 * norm;
}

const FINISH = DEMOS[0].path[DEMOS[0].path.length-1];
const SPAWN = DEMOS[0].path[0];

const SAFE = new Set();
const YMAP = {};
const CELL = 1.0;
for (const d of DEMOS) for (const f of d.path) {
  const k = Math.round(f.x/CELL)+","+Math.round(f.z/CELL);
  SAFE.add(k);
  if (YMAP[k] === undefined) YMAP[k] = f.y;
}
function isSafe(x,z) {
  const cx=Math.round(x/CELL), cz=Math.round(z/CELL);
  return SAFE.has(cx+","+cz);
}
function getY(x,z) {
  const cx=Math.round(x/CELL), cz=Math.round(z/CELL);
  if (YMAP[cx+","+cz] !== undefined) return YMAP[cx+","+cz];
  for (let r=1;r<=5;r++) for (let dx=-r;dx<=r;dx++) for (let dz=-r;dz<=r;dz++) {
    const k=(cx+dx)+","+(cz+dz);
    if (YMAP[k] !== undefined) return YMAP[k];
  }
  return SPAWN.y;
}

const IN=10, H1=48, H2=24, OUT=2;
function rnd(){ return (Math.random()-0.5)*0.3; }
let W1=Array.from({length:H1},()=>Array.from({length:IN},rnd));
let B1=Array.from({length:H1},()=>0);
let W2=Array.from({length:H2},()=>Array.from({length:H1},rnd));
let B2=Array.from({length:H2},()=>0);
let W3=Array.from({length:OUT},()=>Array.from({length:H2},rnd));
let B3=Array.from({length:OUT},()=>0);
try{
  const w=JSON.parse(fs.readFileSync(WF,"utf-8"));
  W1=w.W1;B1=w.B1;W2=w.W2;B2=w.B2;W3=w.W3;B3=w.B3;
  console.log("loaded weights");
}catch(e){console.log("fresh");}

function relu(x){return x>0?x:0;}
function tanh(x){return Math.tanh(x);}
function fwd(inp){
  const h1=new Array(H1);
  for(let i=0;i<H1;i++){let s=B1[i];for(let j=0;j<IN;j++)s+=W1[i][j]*inp[j];h1[i]=relu(s);}
  const h2=new Array(H2);
  for(let i=0;i<H2;i++){let s=B2[i];for(let j=0;j<H1;j++)s+=W2[i][j]*h1[j];h2[i]=relu(s);}
  const o=new Array(OUT);
  for(let i=0;i<OUT;i++){let s=B3[i];for(let j=0;j<H2;j++)s+=W3[i][j]*h2[j];o[i]=tanh(s);}
  return {o,h1,h2};
}
function mkIn(x,z,prevX,prevZ){
  const dx = FINISH.x - x, dz = FINISH.z - z;
  const dist = Math.hypot(dx,dz) || 1;
  const vx = x - prevX, vz = z - prevZ;
  return [dx/100, dz/100, dx/dist, dz/dist, dist/100, vx/SPEED, vz/SPEED, Math.sin(x/50), Math.sin(z/50), dist < 20 ? 1 : 0];
}
function mkTgt(curX, curZ, nextX, nextZ){
  let dx = nextX - curX, dz = nextZ - curZ;
  const len = Math.hypot(dx,dz) || 1;
  return [dx/len, dz/len];
}

const BETA1=0.9, BETA2=0.999, EPS=1e-8;
function zeros(arr){
  if (Array.isArray(arr[0])) return arr.map(r=>r.map(()=>0));
  return arr.map(()=>0);
}
let M={W1:zeros(W1),B1:zeros(B1),W2:zeros(W2),B2:zeros(B2),W3:zeros(W3),B3:zeros(B3)};
let V={W1:zeros(W1),B1:zeros(B1),W2:zeros(W2),B2:zeros(B2),W3:zeros(W3),B3:zeros(B3)};
let t=0;
function adamUpdate(param, grad, m, v, lr, scale){
  scale = scale || 1;
  if (Array.isArray(param[0])) {
    for (let i=0;i<param.length;i++) for (let j=0;j<param[i].length;j++) {
      m[i][j] = BETA1*m[i][j] + (1-BETA1)*grad[i][j];
      v[i][j] = BETA2*v[i][j] + (1-BETA2)*grad[i][j]*grad[i][j];
      const mh = m[i][j]/(1-Math.pow(BETA1,t));
      const vh = v[i][j]/(1-Math.pow(BETA2,t));
      param[i][j] -= lr*scale*mh/(Math.sqrt(vh)+EPS);
    }
  } else {
    for (let i=0;i<param.length;i++) {
      m[i] = BETA1*m[i] + (1-BETA1)*grad[i];
      v[i] = BETA2*v[i] + (1-BETA2)*grad[i]*grad[i];
      const mh = m[i]/(1-Math.pow(BETA1,t));
      const vh = v[i]/(1-Math.pow(BETA2,t));
      param[i] -= lr*scale*mh/(Math.sqrt(vh)+EPS);
    }
  }
}

function backprop(inp, tgt, lr, scale){
  const {o,h1,h2}=fwd(inp);
  const dO=[2*(o[0]-tgt[0]), 2*(o[1]-tgt[1])];
  for (let i=0;i<OUT;i++) if (Math.abs(dO[i])>1) dO[i]=Math.sign(dO[i]);
  const gW3=Array.from({length:OUT},()=>Array(H2).fill(0));
  const gB3=dO.slice();
  for(let i=0;i<OUT;i++) for(let j=0;j<H2;j++) gW3[i][j]=dO[i]*h2[j];
  const dH2=new Array(H2).fill(0);
  for(let j=0;j<H2;j++){
    for(let i=0;i<OUT;i++) dH2[j]+=dO[i]*W3[i][j];
    if(h2[j]<=0) dH2[j]=0;
    if(Math.abs(dH2[j])>1) dH2[j]=Math.sign(dH2[j]);
  }
  const gW2=Array.from({length:H2},()=>Array(H1).fill(0));
  const gB2=dH2.slice();
  for(let i=0;i<H2;i++) for(let j=0;j<H1;j++) gW2[i][j]=dH2[i]*h1[j];
  const dH1=new Array(H1).fill(0);
  for(let j=0;j<H1;j++){
    for(let i=0;i<H2;i++) dH1[j]+=dH2[i]*W2[i][j];
    if(h1[j]<=0) dH1[j]=0;
    if(Math.abs(dH1[j])>1) dH1[j]=Math.sign(dH1[j]);
  }
  const gW1=Array.from({length:H1},()=>Array(IN).fill(0));
  const gB1=dH1.slice();
  for(let i=0;i<H1;i++) for(let j=0;j<IN;j++) gW1[i][j]=dH1[i]*inp[j];
  t++;
  adamUpdate(W1,gW1,M.W1,V.W1,lr,scale);
  adamUpdate(B1,gB1,M.B1,V.B1,lr,scale);
  adamUpdate(W2,gW2,M.W2,V.W2,lr,scale);
  adamUpdate(B2,gB2,M.B2,V.B2,lr,scale);
  adamUpdate(W3,gW3,M.W3,V.W3,lr,scale);
  adamUpdate(B3,gB3,M.B3,V.B3,lr,scale);
  return dO[0]*dO[0]+dO[1]*dO[1];
}

function getW(){ return JSON.stringify({W1,B1,W2,B2,W3,B3}); }
function saveW(){ fs.writeFileSync(WF, getW()); }
function saveBackup(){ fs.writeFileSync(WB, getW()); }
function loadBackup(){
  try {
    const w=JSON.parse(fs.readFileSync(WB,"utf-8"));
    W1=w.W1;B1=w.B1;W2=w.W2;B2=w.B2;W3=w.W3;B3=w.B3;
    saveW();
    console.log(">>> ROLLBACK to backup weights");
    return true;
  } catch(e){ return false; }
}

function train(epochs, lr){
  lr = lr || 0.003;
  const samples=[];
  for (const d of DEMOS) {
    for(let i=1;i<d.path.length-1;i++){
      samples.push({
        inp:mkIn(d.path[i].x, d.path[i].z, d.path[i-1].x, d.path[i-1].z),
        tgt:mkTgt(d.path[i].x, d.path[i].z, d.path[i+1].x, d.path[i+1].z),
        w: d.weight
      });
    }
  }
  console.log("training on " + samples.length + " samples x " + epochs);
  const t0=Date.now();
  for(let ep=0;ep<epochs;ep++){
    let L=0, nan=0;
    for(let i=samples.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[samples[i],samples[j]]=[samples[j],samples[i]];}
    for(const s of samples){
      const l=backprop(s.inp,s.tgt,lr,s.w);
      if(isNaN(l))nan++; L+=l;
    }
    if(ep%25===0||ep===epochs-1) console.log("ep "+ep+"/"+epochs+" loss="+(L/samples.length).toFixed(6)+" nan="+nan+" | "+((Date.now()-t0)/1000).toFixed(0)+"s");
  }
  saveW();
  saveBackup();
  console.log("done in "+((Date.now()-t0)/1000).toFixed(1)+"s");
}

function rlUpdate(steps, reward, lr){
  if (steps.length === 0) return;
  const scale = Math.sign(reward) * Math.min(Math.abs(reward), 0.3);
  for (let i = 0; i < steps.length; i++) {
    const decay = Math.pow(0.995, steps.length - i);
    backprop(steps[i].inp, steps[i].action, lr, scale * decay);
  }
}

